public TFMRegistrationCollectors registrationCollectors(TFMRequestElement _request = null)
{
    TFMRegistrationCollectors ret = TFMRegistrationCollectors::Construct();
    TFMRegistrationCollectorSignature  coll = new TFMRegistrationCollectorSignature(1,extendedTypeStr(Sign),"@TFM:Sign","@TFM:Sign","@TFM:Sign");        
    ret.addCollector(coll);
    return ret;
}

public void new()
{
    super();
    components.addComponent(new TFMLogicComponentDataContext());

}

public TFMPostResponseData post()
{
    TFMPostResponseData             postElement     = TFMPostResponseData::Construct();
    TFMLogicComponentDataContext    dataContext     = components.getComponent(classStr(TFMLogicComponentDataContext));
    Common                          dataToAttachTo  = dataContext.getData(request);
    str                             signBase64      = this.getFieldValue(extendedTypeStr(Sign));

    if (signBase64 && dataToAttachTo)
    {
        TFMHelper::attachBase64ToCommon(dataToAttachTo,signBase64,'.png');
    }
    postElement.parmResponseText(strFmt("@TFM:ImageAttachedto", TFMHelper::descriptionFromCommon(dataToAttachTo)));

    return postElement;
}

public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    TFMLogicComponentDataContext    dataContext     = components.getComponent(classStr(TFMLogicComponentDataContext));
